style.css:
/* Crystal Haze — Brave Search */

:root {
  /* swap these values to customize the palette */
  --my-bg: #e9ebef;
  --my-surface: #f5f6f8;
  --my-card: rgba(255, 255, 255, 0.72);
  --my-text: #30343b;
  --my-muted: #858b96;
  --my-border: rgba(130, 140, 155, 0.22);
  --my-accent: #8293aa;
}

/* frosted page background */
body {
  background: linear-gradient(145deg, #f4f5f7, #dfe3e9) !important;
  color: var(--my-text) !important;
}

/* clean typography */
body, input, button {
  font-family: "Inter", "Segoe UI", sans-serif !important;
}

/* search fields */
input[type="text"],
input[type="search"] {
  background: var(--my-card) !important;
  color: var(--my-text) !important;
  border: 1px solid var(--my-border) !important;
  border-radius: 18px !important;
  box-shadow: 0 5px 20px rgba(80, 90, 110, 0.07) !important;
}

/* links */
a {
  color: #647c99 !important;
}

/* images */
img {
  border-radius: 10px;
}

/* subtle selection */
::selection {
  background: #c5cfdd !important;
  color: #30343b !important;
}

/* soft scrollbar */
* {
  scrollbar-color: #b6beca transparent !important;
}
